'use strict';
const categories=['說話的藝術','文化底蘊','知識見解','文字素養','好好說話'];
const kinds=['原創觀點','古典短句','文學節選','古詩'];
const tagOptions=['全部情境','提問','澄清','拒絕','安慰','道歉','鼓勵','感謝','界線','不同意','請託','文化交流','文字表達','求證','傾聽'];
const descriptions=['把心裡的意思，說到對方聽得懂。','從文字與日常，讀懂更寬的人情。','留一點好奇，也留一點求證的耐心。','讓每個字，都更靠近你想說的意思。','真誠有溫度，關係也有清楚的界線。'];
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const taipeiDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const day=taipeiDate();const dayNumber=Math.floor(Date.parse(day)/86400000);
let bank=[],daily=[],view='today',filter='全部',kindFilter='全部類型',tagFilter='全部情境',selectedId=null;
let state={};try{state=JSON.parse(localStorage.getItem('shiju-v1')||'{}')||{}}catch{}
let saved=Array.isArray(state.saved)?[...new Set(state.saved.filter(Number.isInteger))]:[];
let read=state.day===day&&state.edition===3&&Array.isArray(state.read)?[...new Set(state.read)]:[];
let notes=state.notes&&typeof state.notes==='object'&&!Array.isArray(state.notes)?state.notes:{};
let labels=state.labels&&typeof state.labels==='object'&&!Array.isArray(state.labels)?state.labels:{};
let reviewHistory=state.reviewHistory&&typeof state.reviewHistory==='object'&&!Array.isArray(state.reviewHistory)?state.reviewHistory:{};
let practice=typeof state.practice==='string'?state.practice:'';
let reviewed=state.day===day?state.reviewed:null;
function persist(){try{localStorage.setItem('shiju-v1',JSON.stringify({saved,read,day,edition:3,practice,notes,labels,reviewHistory,reviewed}));return true}catch{toast('無法儲存，請確認瀏覽器允許本機儲存。');return false}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
// Each theme is a stable 28-item ring. Four per day means any seven consecutive days cover every item exactly once.
function selectDaily(n){return categories.flatMap((c,ci)=>{const pool=bank.filter(q=>q.category===c).sort((a,b)=>((a.id*37+ci*13)%149)-((b.id*37+ci*13)%149));const start=(((n%7)+7)%7)*4;return pool.slice(start,start+4)})}
const itemById=id=>bank.find(q=>q.id===id);
function setView(next){view=next;filter='全部';kindFilter='全部類型';tagFilter='全部情境';$('#search').value='';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});render()}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();if(selectedId===id&&$('#detail').open)updateDetailSave();}
function updateDetailSave(){const b=$('#detailSave');if(b){b.textContent=saved.includes(selectedId)?'已收藏 · 取消收藏':'收藏這句話';b.setAttribute('aria-pressed',String(saved.includes(selectedId)))}}
function markRead(id){if(daily.some(q=>q.id===id)&&!read.includes(id)){read.push(id);persist();renderProgress()}}
function renderProgress(){read=read.filter(id=>daily.some(q=>q.id===id));$('#savedCount').textContent=saved.length;$('#readLabel').textContent=`已讀 ${read.length} / 20 則`;$('#bar').style.width=`${read.length*5}%`;$('#progressTrack').setAttribute('aria-valuenow',read.length);$('#encourage').textContent=read.length===20?'今天的 20 則已讀完。把其中一句，帶進生活裡。':'讀解與練習開啟後會記錄已讀；慢慢讀，也很好。'}
function buttons(values,current,attr){return values.map(v=>`<button class="filter ${v===current?'active':''}" ${attr}="${escapeHTML(v)}" aria-pressed="${v===current}">${escapeHTML(v)}</button>`).join('')}
function card(q){return `<article class="card"><div class="card-top"><span class="tag">${q.kind}</span><button class="bookmark ${saved.includes(q.id)?'saved':''}" data-save="${q.id}" aria-label="${saved.includes(q.id)?'取消收藏':'收藏金句'}" aria-pressed="${saved.includes(q.id)}">${saved.includes(q.id)?'▣':'♧'}</button></div><div class="quote-mark">“</div><h3 class="quote">${escapeHTML(q.quote)}</h3><div class="source">${escapeHTML(q.source)}</div><div class="card-labels">${[...new Set([...(q.tags||[]),...(Array.isArray(labels[q.id])?labels[q.id]:[])])].map(t=>`<span>${escapeHTML(t)}</span>`).join('')}${notes[q.id]?'<span>有我的心得</span>':''}</div><div class="card-bottom"><button class="read-detail" data-detail="${q.id}">讀解與生活練習 ＋</button><span class="read-state ${read.includes(q.id)?'done':''}">${read.includes(q.id)?'✓ 已閱讀':'約 1 分鐘'}</span></div></article>`}
function feature(){const q=daily.find(q=>q.kind!=='原創觀點')||daily[(dayNumber%20+20)%20];$('#featured').innerHTML=`<div class="feature-kicker">今日主句 <span>ONE THOUGHT TO KEEP</span></div><div class="featured-body"><div><span class="tag">${q.category} · ${q.kind}</span><h1>${escapeHTML(q.quote)}</h1><p class="featured-source">${escapeHTML(q.source)}</p><div class="feature-actions"><button class="primary" data-detail="${q.id}">讀解與生活練習</button><button class="quiet" data-save="${q.id}" aria-pressed="${saved.includes(q.id)}">${saved.includes(q.id)?'已收藏':'收藏主句'}</button></div></div><div class="feature-margin" aria-hidden="true"><span>拾一好句<br>留一寸光</span><small>SHIJU · DAILY JOURNAL</small></div></div><p class="feature-footnote">今天不必記住所有話。留下一句，試著在生活裡用一次。<span>主句已包含在今日 20 則內</span></p>`}
function reviewCard(){const candidates=saved.map(itemById).filter(Boolean).sort((a,b)=>(reviewHistory[a.id]||'').localeCompare(reviewHistory[b.id]||'')||a.id-b.id);const q=reviewed!==null&&saved.includes(reviewed)?itemById(reviewed):candidates[0];if(!q){$('#review').innerHTML='<div class="review-empty"><span>讓好句子，再遇見你。</span><p>收藏喜歡的句子後，這裡會每天帶回一則，陪你想想最近用得上的場合。</p></div>';return}$('#review').innerHTML=`<div class="review-heading"><span>溫故一句 <small>FROM YOUR BOOKMARKS</small></span><span>${reviewed===q.id?'今天已複習':'收藏裡的一次重逢'}</span></div><p class="review-quote">${escapeHTML(q.quote)}</p><p class="review-prompt">最近有哪個場合用得上？${notes[q.id]?`<br><span>我的心得：${escapeHTML(notes[q.id])}</span>`:''}</p><div><button class="text-button" data-detail="${q.id}">重讀這句話</button><button class="text-button" data-review="${q.id}" ${reviewed===q.id?'disabled':''}>${reviewed===q.id?'✓ 已複習':'記下今天的複習'}</button></div>`}
function render(){if(!bank.length)return;renderProgress();const isPractice=view==='practice';const today=view==='today';$('#featured').hidden=!today;$('#review').hidden=!(today||view==='saved');$('#dailyProgress').hidden=!today;$('#practicePanel').hidden=!isPractice;$('#cards').hidden=isPractice;$('#filters').hidden=isPractice;$('#kindFilters').hidden=isPractice;$('#tagFilters').hidden=view!=='saved';$('.search').hidden=isPractice;$('#libraryNote').hidden=!today;$('#pageLabel').textContent={today:'今日拾句',saved:'我的書籤',practice:'表達練習',library:'全句庫'}[view];$('#sectionTitle').textContent={today:'今日五輯',saved:'我的書籤',practice:'讓好句子成為你的話',library:'慢慢讀，全句庫'}[view];$('#sectionDesc').textContent={today:'五個主題，各拾四句。連續七天，讀見 140 則不同的文字。',saved:'留下句子，也留下當下的自己。用情境找回你的表達靈感。',practice:'一段改寫，一點進步。你的練習會保存在這個瀏覽器。',library:'140 則原創與古典文字。可搜尋作者、作品、句子與讀解。'}[view];$('#filters').innerHTML=buttons(['全部',...categories],filter,'data-category');$('#kindFilters').innerHTML=buttons(['全部類型',...kinds],kindFilter,'data-kind');$('#tagFilters').innerHTML=buttons(tagOptions,tagFilter,'data-tag');const term=$('#search').value.trim();const items=(view==='saved'?bank.filter(q=>saved.includes(q.id)):view==='library'?bank:daily).filter(q=>(filter==='全部'||q.category===filter)&&(kindFilter==='全部類型'||q.kind===kindFilter)&&(tagFilter==='全部情境'||[...(q.tags||[]),...(Array.isArray(labels[q.id])?labels[q.id]:[])].includes(tagFilter))&&[q.quote,q.category,q.insight,q.source,q.kind,notes[q.id]||''].join('').includes(term));$('#cards').classList.toggle('chapters',today);if(!items.length){$('#cards').innerHTML=`<div class="empty">${term||filter!=='全部'||kindFilter!=='全部類型'||tagFilter!=='全部情境'?'沒有符合的句子，試試其他關鍵字或篩選。':view==='saved'?'還沒有收藏。從今日主句開始，留下讓你有感的文字。':'此處還沒有句子。'}</div>`}else if(today){$('#cards').innerHTML=categories.map((c,i)=>{const group=items.filter(q=>q.category===c);if(!group.length)return '';return `<details class="chapter" ${i===0||filter!=='全部'||term||kindFilter!=='全部類型'?'open':''}><summary><span class="chapter-title">${c}<small>${descriptions[i]}</small></span><span class="chapter-count">${group.length} 則<span class="chapter-chevron">⌄</span></span></summary><div class="chapter-cards">${group.map(card).join('')}</div></details>`}).join('')}else $('#cards').innerHTML=items.map(card).join('');if(today)feature();if(today||view==='saved')reviewCard();}
function openDetail(id){const q=itemById(id);if(!q)return;selectedId=id;markRead(id);render();const custom=Array.isArray(labels[id])?labels[id]:[];$('#detailBody').innerHTML=`<span class="tag">${q.category} · ${q.kind}</span><h2>${escapeHTML(q.quote)}</h2><p class="detail-source">${escapeHTML(q.source)}</p>${q.url?`<p class="citation"><a href="${escapeHTML(q.url)}" target="_blank" rel="noopener noreferrer">閱讀原文與出處</a><br><small>公版原文節選；標點與異體字依閱讀需要整理，傳本差異請見來源。</small></p>`:'<p class="citation">拾句原創觀點，非歷史人物引言。</p>'}${q.background?`<details class="source-context"><summary>讀懂原文 · 背景與詞義</summary><h3>作品背景</h3><p>${escapeHTML(q.background)}</p><h3>詞義與難字</h3><p>${escapeHTML(q.glossary)}</p></details>`:''}<h3>拾句讀解 · 現代延伸</h3><p>${escapeHTML(q.insight)}</p><section class="dialogue"><h3>生活裡，這樣說</h3><span class="scene-label">${escapeHTML(q.dialogue.scene)} · 拾句情境示例</span><div class="before"><small>容易脫口而出</small><p>${escapeHTML(q.dialogue.before)}</p></div><div class="after"><small>試著換個說法</small><p>${escapeHTML(q.dialogue.after)}</p></div><small>示例提供表達方向，可依關係與場合調整。</small></section><h3>今天的小練習</h3><p>${escapeHTML(q.exercise)}</p><button class="text-button" id="useExercise">帶到表達練習</button><section class="personal"><h3>我的心得</h3><label for="quoteNote">這句讓你想到誰、哪件事，或想怎麼用？</label><textarea id="quoteNote" maxlength="2000" placeholder="留下你自己的理解……">${escapeHTML(notes[id]||'')}</textarea><fieldset><legend>為這句加上情境標籤</legend><div class="note-tags">${tagOptions.slice(1).map(t=>`<label><input type="checkbox" name="noteTag" value="${t}" ${custom.includes(t)?'checked':''}>${t}</label>`).join('')}</div></fieldset><p class="personal-hint">儲存心得會同時收藏這句。內容僅保存在此瀏覽器。</p><button class="primary" id="saveNote">儲存心得與標籤</button><button class="quiet" id="detailSave" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'已收藏 · 取消收藏':'收藏這句話'}</button></section>`;$('#detailSave').onclick=()=>toggleSave(id);$('#saveNote').onclick=()=>{const text=$('#quoteNote').value.trim();const selected=Array.from(document.querySelectorAll('input[name="noteTag"]:checked')).map(x=>x.value);notes[id]=text;labels[id]=selected;if(!saved.includes(id))saved.push(id);if(persist()){toast('心得與標籤已儲存，也已加入收藏。');render();updateDetailSave()}};$('#useExercise').onclick=()=>{practice=`「${q.quote}」\n\n今天的小練習：${q.exercise}\n\n我的改寫：\n`;$('#practiceText').value=practice;persist();$('#detail').close();selectedId=null;setView('practice');$('#practiceText').focus()};$('#detail').showModal();$('#detail').scrollTop=0;}
function handleQuoteClick(e){const save=e.target.closest('[data-save]');if(save){toggleSave(Number(save.dataset.save));return}const detail=e.target.closest('[data-detail]');if(detail){openDetail(Number(detail.dataset.detail));return}const review=e.target.closest('[data-review]');if(review){reviewed=Number(review.dataset.review);reviewHistory[reviewed]=day;if(persist()){reviewCard();toast('已記下今天的複習。')}}}
['#cards','#featured','#review'].forEach(s=>$(s).addEventListener('click',handleQuoteClick));
$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(b){filter=b.dataset.category;render()}};$('#kindFilters').onclick=e=>{const b=e.target.closest('[data-kind]');if(b){kindFilter=b.dataset.kind;render()}};$('#tagFilters').onclick=e=>{const b=e.target.closest('[data-tag]');if(b){tagFilter=b.dataset.tag;render()}};
$('#search').oninput=render;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{selectedId=null});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#practiceText').value=practice;$('#savePractice').onclick=()=>{practice=$('#practiceText').value;if(!practice.trim())return toast('先寫下一句你的練習吧。');if(persist())toast('練習已儲存，讓表達慢慢進步。')};$('#date').textContent=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'long'}).format(new Date());$('#date').onclick=()=>toast('依台北日期輪替：每日 20 則，連續七天不重複。');setInterval(()=>{if(taipeiDate()!==day)location.reload()},60000);
async function init(){try{if(Array.isArray(globalThis.SHIJU_QUOTES)){bank=globalThis.SHIJU_QUOTES}else{const response=await fetch('quotes.json');if(!response.ok)throw Error('Load failed');bank=await response.json();}saved=saved.filter(id=>itemById(id));daily=selectDaily(dayNumber);render();$('#loading').hidden=true}catch{$('#loading').innerHTML='<p>暫時無法載入句庫，請稍後重試。</p><button class="primary" id="retry">重新載入</button>';$('#retry').onclick=init}}init();

// Desktop installation is progressive enhancement; the downloadable HTML also works on file://.
if(typeof navigator!=='undefined'){
 let installPrompt=null;
 const status=$('#offlineStatus');const install=$('#installApp');
 if(globalThis.SHIJU_QUOTES){status.textContent='獨立離線版 · 已內含全部句庫';install.hidden=true;}
 else if('serviceWorker' in navigator&&location.protocol==='https:'){
 navigator.serviceWorker.register('./sw.js').then(()=>Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Offline preparation timed out')),30000))])).then(async()=>{const cached=await caches.match(new URL('./quotes.json',location.href).href);status.textContent=cached?'已可離線使用':'離線資料尚未完成，請保持連線';}).catch(()=>{status.textContent='此瀏覽器無法準備離線快取，請下載獨立離線版';});
 }else{status.textContent='可下載獨立離線版使用';}
 globalThis.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;install.textContent='安裝拾句到桌面';});
 globalThis.addEventListener('appinstalled',()=>{installPrompt=null;install.textContent='已安裝到桌面';install.disabled=true;});
 install.onclick=async()=>{if(!installPrompt){toast('請使用瀏覽器的安裝功能，或依下方 Safari 說明加入桌面。');return}await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;};
}
